-- =====================================================================
-- 097  Workflows G to M from "Hostel Database Design and Data Model, by Workflow", v2.1 (1 Oct 2026).
--      Generated by scripts/gen-097.py from the document (docs/source/v21_tables.json):
--      the 28 tables the database did not have, and the items v2.1 adds to tables that exist.
--      Every column carries the document's description as a comment.
-- =====================================================================
-- G3 Menu_Plan: one row per dish list for one meal of one cuisine on one day
CREATE TABLE hostel.menu_plan (
  menu_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  mess_id bigint NOT NULL REFERENCES hostel.mess_master,
  cuisine varchar(40) NOT NULL CHECK (cuisine IN ('South', 'North', 'Continental')),
  menu_date date NOT NULL,
  meal varchar(40) NOT NULL CHECK (meal IN ('Breakfast', 'Lunch', 'Evening_Snacks', 'Dinner')),
  dishes text NOT NULL,
  approved_by varchar(20) NOT NULL REFERENCES ref.staff_master,
  created_at timestamptz NOT NULL DEFAULT now(), created_by varchar(20), updated_at timestamptz, updated_by varchar(20)
);
COMMENT ON TABLE hostel.menu_plan IS 'v2.1 G3 Menu_Plan. One row per: dish list for one meal of one cuisine on one day';

-- G4 Meal_Attendance: one row per meal taken by a student
CREATE TABLE hostel.meal_attendance (
  student_id varchar(20) NOT NULL REFERENCES ref.student_master,
  meal_date date NOT NULL,
  meal varchar(40) NOT NULL CHECK (meal IN ('Breakfast', 'Lunch', 'Evening_Snacks', 'Dinner')),
  mess_id bigint REFERENCES hostel.mess_master,
  scanned_at timestamptz,
  PRIMARY KEY (student_id, meal_date, meal),
  created_at timestamptz NOT NULL DEFAULT now(), created_by varchar(20), updated_at timestamptz, updated_by varchar(20)
);
COMMENT ON TABLE hostel.meal_attendance IS 'v2.1 G4 Meal_Attendance. One row per: meal taken by a student';

-- G5 Mess_Issue: one row per issue of provisions from the mess store to the kitchen
CREATE TABLE hostel.mess_issue (
  issue_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  mess_id bigint NOT NULL REFERENCES hostel.mess_master,
  issue_date date NOT NULL,
  meal varchar(40) NOT NULL,
  student_strength integer,
  issued_by varchar(20) REFERENCES ref.staff_master,
  acknowledged_by varchar(20) NOT NULL REFERENCES ref.staff_master,
  created_at timestamptz NOT NULL DEFAULT now(), created_by varchar(20), updated_at timestamptz, updated_by varchar(20)
);
COMMENT ON TABLE hostel.mess_issue IS 'v2.1 G5 Mess_Issue. One row per: issue of provisions from the mess store to the kitchen';

-- G6 Mess_Issue_Line: one row per item on a mess issue
CREATE TABLE hostel.mess_issue_line (
  issue_id bigint NOT NULL REFERENCES hostel.mess_issue,
  sku varchar(30) NOT NULL REFERENCES portal.material,
  qty numeric(12,3) NOT NULL,
  expiry_date date,
  PRIMARY KEY (issue_id, sku),
  created_at timestamptz NOT NULL DEFAULT now(), created_by varchar(20), updated_at timestamptz, updated_by varchar(20)
);
COMMENT ON TABLE hostel.mess_issue_line IS 'v2.1 G6 Mess_Issue_Line. One row per: item on a mess issue';

-- G7 Mess_Daily_Record: one row per meal served in a mess on a day
CREATE TABLE hostel.mess_daily_record (
  mess_id bigint NOT NULL REFERENCES hostel.mess_master,
  record_date date NOT NULL,
  meal varchar(60) NOT NULL,
  meals_planned numeric(12,2) NOT NULL,
  meals_served numeric(12,2),
  prep_wastage_kg numeric(12,3) NOT NULL,
  plate_wastage_kg numeric(12,3) NOT NULL,
  menu_followed boolean NOT NULL DEFAULT false,
  deviation_reason text,
  recorded_by varchar(20) REFERENCES ref.staff_master,
  PRIMARY KEY (mess_id, record_date, meal),
  created_at timestamptz NOT NULL DEFAULT now(), created_by varchar(20), updated_at timestamptz, updated_by varchar(20)
);
COMMENT ON TABLE hostel.mess_daily_record IS 'v2.1 G7 Mess_Daily_Record. One row per: meal served in a mess on a day';

-- G8 Mess_Feedback: one row per feedback or grievance of one student about one meal
CREATE TABLE hostel.mess_feedback (
  feedback_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  entry_type varchar(40) NOT NULL CHECK (entry_type IN ('Feedback', 'Grievance')),
  student_id varchar(20) NOT NULL REFERENCES ref.student_master,
  mess_id bigint NOT NULL REFERENCES hostel.mess_master,
  meal_date date NOT NULL,
  slot varchar(40) NOT NULL CHECK (slot IN ('Breakfast', 'Lunch', 'Evening_Snacks', 'Dinner')),
  aspect varchar(40) NOT NULL CHECK (aspect IN ('Quality', 'Quantity', 'Both')),
  rating integer,
  details text,
  photo_doc_id uuid REFERENCES shared.document,
  submitted_at timestamptz DEFAULT now(),
  action_taken text,
  action_by varchar(20) REFERENCES ref.staff_master,
  closed_at timestamptz,
  status varchar(40) NOT NULL DEFAULT 'Open' CHECK (status IN ('Open', 'Replied', 'Closed')),
  created_at timestamptz NOT NULL DEFAULT now(), created_by varchar(20), updated_at timestamptz, updated_by varchar(20)
);
COMMENT ON TABLE hostel.mess_feedback IS 'v2.1 G8 Mess_Feedback. One row per: feedback or grievance of one student about one meal';

-- G9 Mess_Grievance_Summary: one row per mess, date and slot with grievances (kept by the software)
CREATE TABLE hostel.mess_grievance_summary (
  mess_id bigint NOT NULL REFERENCES hostel.mess_master,
  meal_date date NOT NULL,
  slot varchar(60) NOT NULL,
  students_count numeric(12,2),
  mess_strength numeric(12,2),
  is_significant boolean NOT NULL DEFAULT false,
  main_aspect numeric(12,2),
  raised_to_management_at timestamptz,
  action_summary text,
  status varchar(40) NOT NULL DEFAULT 'Open' CHECK (status IN ('Open', 'Action_Taken', 'Closed')),
  PRIMARY KEY (mess_id, meal_date, slot),
  created_at timestamptz NOT NULL DEFAULT now(), created_by varchar(20), updated_at timestamptz, updated_by varchar(20)
);
COMMENT ON TABLE hostel.mess_grievance_summary IS 'v2.1 G9 Mess_Grievance_Summary. One row per: mess, date and slot with grievances (kept by the software)';

-- H2 Ticket_Event: one row per step in the life of a ticket
CREATE TABLE hostel.ticket_event (
  ticket_id bigint NOT NULL REFERENCES infra.maintenance_ticket,
  event_no bigint NOT NULL,
  action varchar(40) CHECK (action IN ('Raised', 'Verified', 'Rejected', 'Escalated', 'Assigned', 'Started', 'Closure_Report', 'Confirmed', 'Auto_Closed', 'Follow_Up_Opened')),
  actor_id varchar(20) REFERENCES ref.staff_master,
  role_code varchar(30) REFERENCES portal.role,
  event_at timestamptz,
  note text,
  PRIMARY KEY (ticket_id, event_no),
  created_at timestamptz NOT NULL DEFAULT now(), created_by varchar(20), updated_at timestamptz, updated_by varchar(20)
);
COMMENT ON TABLE hostel.ticket_event IS 'v2.1 H2 Ticket_Event. One row per: step in the life of a ticket';

-- H3 Checklist_Template: one row per checklist, such as the Floor In-charge daily inspection
CREATE TABLE hostel.checklist_template (
  template_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  template_name text NOT NULL,
  role_code varchar(30) NOT NULL REFERENCES portal.role,
  frequency varchar(40) NOT NULL CHECK (frequency IN ('Daily', 'Weekly', 'Monthly')),
  scope varchar(40) NOT NULL CHECK (scope IN ('Hostel', 'Floor', 'Room', 'Mess', 'Store')),
  answer_type varchar(40) NOT NULL CHECK (answer_type IN ('Yes_No', 'OK_NotOK', 'GYRC')),
  reviewer_role varchar(30) NOT NULL REFERENCES portal.role,
  version numeric(12,2),
  status varchar(40) NOT NULL CHECK (status IN ('Active', 'Retired')),
  created_at timestamptz NOT NULL DEFAULT now(), created_by varchar(20), updated_at timestamptz, updated_by varchar(20)
);
COMMENT ON TABLE hostel.checklist_template IS 'v2.1 H3 Checklist_Template. One row per: checklist, such as the Floor In-charge daily inspection';

-- H4 Checklist_Item: one row per line on a checklist
CREATE TABLE hostel.checklist_item (
  template_id bigint NOT NULL REFERENCES hostel.checklist_template,
  item_no bigint NOT NULL,
  section text,
  item_text text NOT NULL,
  category_id varchar(20) REFERENCES infra.maintenance_category,
  ticket_on_fail boolean NOT NULL DEFAULT false,
  PRIMARY KEY (template_id, item_no),
  created_at timestamptz NOT NULL DEFAULT now(), created_by varchar(20), updated_at timestamptz, updated_by varchar(20)
);
COMMENT ON TABLE hostel.checklist_item IS 'v2.1 H4 Checklist_Item. One row per: line on a checklist';

-- H5 Checklist_Submission: one row per checklist filled for one place and period
CREATE TABLE hostel.checklist_submission (
  submission_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  template_id bigint NOT NULL REFERENCES hostel.checklist_template,
  facility_id varchar(30) NOT NULL REFERENCES hostel.hostel_profile,
  zone_id varchar(30) REFERENCES infra.zone,
  period_date date NOT NULL,
  shift varchar(40) CHECK (shift IN ('Morning', 'Evening')),
  submitted_by varchar(20) REFERENCES ref.staff_master,
  submitted_at timestamptz DEFAULT now(),
  overall_status varchar(40) NOT NULL CHECK (overall_status IN ('Satisfactory', 'Minor_Corrections', 'Needs_Attention', 'Urgent_Action')),
  reviewed_by varchar(20) NOT NULL REFERENCES ref.staff_master,
  reviewed_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(), created_by varchar(20), updated_at timestamptz, updated_by varchar(20)
);
COMMENT ON TABLE hostel.checklist_submission IS 'v2.1 H5 Checklist_Submission. One row per: checklist filled for one place and period';

-- H6 Checklist_Response: one row per answer to one checklist line
CREATE TABLE hostel.checklist_response (
  response_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  submission_id bigint NOT NULL REFERENCES hostel.checklist_submission,
  item_no bigint NOT NULL,
  space_id varchar(30) REFERENCES infra.space,
  answer varchar(40) NOT NULL,
  remarks text,
  ticket_id bigint REFERENCES infra.maintenance_ticket,
  created_at timestamptz NOT NULL DEFAULT now(), created_by varchar(20), updated_at timestamptz, updated_by varchar(20)
);
COMMENT ON TABLE hostel.checklist_response IS 'v2.1 H6 Checklist_Response. One row per: answer to one checklist line';

-- H7 Student_Grievance: one row per grievance that is not a repair
CREATE TABLE hostel.student_grievance (
  grievance_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  student_id varchar(20) NOT NULL REFERENCES ref.student_master,
  category varchar(40) NOT NULL CHECK (category IN ('Room_Mate', 'Discipline', 'Mess', 'Staff_Conduct', 'Ragging', 'Safety', 'Other')),
  description text NOT NULL,
  is_confidential boolean NOT NULL DEFAULT false,
  raised_at timestamptz DEFAULT now(),
  assigned_to varchar(20) REFERENCES ref.staff_master,
  action_taken text,
  closed_at timestamptz,
  status varchar(40) NOT NULL DEFAULT 'Open' CHECK (status IN ('Open', 'In_Review', 'Escalated', 'Closed')),
  created_at timestamptz NOT NULL DEFAULT now(), created_by varchar(20), updated_at timestamptz, updated_by varchar(20)
);
COMMENT ON TABLE hostel.student_grievance IS 'v2.1 H7 Student_Grievance. One row per: grievance that is not a repair';

-- J1 Hostel_Facility: one row per facility in a hostel
CREATE TABLE hostel.hostel_facility (
  hostel_facility_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  space_id varchar(30) NOT NULL REFERENCES infra.space,
  facility_type varchar(40) NOT NULL CHECK (facility_type IN ('Library', 'Student_Activity_Centre', 'Play_Room', 'Games_Court', 'Other')),
  facility_name text NOT NULL,
  capacity numeric(12,2) NOT NULL,
  open_time time NOT NULL,
  close_time time NOT NULL,
  point_id bigint REFERENCES hostel.capture_point,
  status varchar(40) NOT NULL CHECK (status IN ('Active', 'Closed')),
  created_at timestamptz NOT NULL DEFAULT now(), created_by varchar(20), updated_at timestamptz, updated_by varchar(20)
);
COMMENT ON TABLE hostel.hostel_facility IS 'v2.1 J1 Hostel_Facility. One row per: facility in a hostel';

-- J2 Facility_Usage: one row per visit of a student to a facility
CREATE TABLE hostel.facility_usage (
  usage_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  hostel_facility_id bigint NOT NULL REFERENCES hostel.hostel_facility,
  student_id varchar(20) NOT NULL REFERENCES ref.student_master,
  usage_date date,
  time_in time NOT NULL,
  time_out time,
  activity text,
  source varchar(40) CHECK (source IN ('Scan', 'Manual')),
  entered_by varchar(20) REFERENCES ref.staff_master,
  created_at timestamptz NOT NULL DEFAULT now(), created_by varchar(20), updated_at timestamptz, updated_by varchar(20)
);
COMMENT ON TABLE hostel.facility_usage IS 'v2.1 J2 Facility_Usage. One row per: visit of a student to a facility';

-- J3 Facility_Day_Register: one row per facility per day
CREATE TABLE hostel.facility_day_register (
  hostel_facility_id bigint NOT NULL REFERENCES hostel.hostel_facility,
  register_date date NOT NULL,
  was_open boolean NOT NULL DEFAULT false,
  closed_reason text,
  students_count numeric(12,2),
  visits_count numeric(12,2),
  peak_hour numeric(12,2),
  remarks text,
  confirmed_by varchar(20) NOT NULL REFERENCES ref.staff_master,
  confirmed_at timestamptz,
  PRIMARY KEY (hostel_facility_id, register_date),
  created_at timestamptz NOT NULL DEFAULT now(), created_by varchar(20), updated_at timestamptz, updated_by varchar(20)
);
COMMENT ON TABLE hostel.facility_day_register IS 'v2.1 J3 Facility_Day_Register. One row per: facility per day';

-- K1 Convention_Hall: one row per convention centre hall
CREATE TABLE hostel.convention_hall (
  hall_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  space_id varchar(30) NOT NULL REFERENCES infra.space,
  hall_name text NOT NULL,
  capacity numeric(12,2) NOT NULL,
  status varchar(40) NOT NULL CHECK (status IN ('Active', 'Closed')),
  created_at timestamptz NOT NULL DEFAULT now(), created_by varchar(20), updated_at timestamptz, updated_by varchar(20)
);
COMMENT ON TABLE hostel.convention_hall IS 'v2.1 K1 Convention_Hall. One row per: convention centre hall';

-- K2 Booking_Slot: one row per bookable time slot of a hall
CREATE TABLE hostel.booking_slot (
  slot_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  hall_id bigint NOT NULL REFERENCES hostel.convention_hall,
  slot_name text NOT NULL,
  start_time time NOT NULL,
  end_time time NOT NULL,
  status varchar(40) NOT NULL CHECK (status IN ('Active', 'Inactive')),
  created_at timestamptz NOT NULL DEFAULT now(), created_by varchar(20), updated_at timestamptz, updated_by varchar(20)
);
COMMENT ON TABLE hostel.booking_slot IS 'v2.1 K2 Booking_Slot. One row per: bookable time slot of a hall';

-- K3 Convention_Booking: one row per booking of a slot on a date
CREATE TABLE hostel.convention_booking (
  booking_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  booking_no text,
  slot_id bigint NOT NULL REFERENCES hostel.booking_slot,
  event_date date NOT NULL,
  student_id varchar(20) NOT NULL REFERENCES ref.student_master,
  occasion_type varchar(40) NOT NULL CHECK (occasion_type IN ('Birthday', 'Prize_Won', 'Placement', 'Other')),
  occasion_details text NOT NULL,
  guest_count numeric(12,2),
  applied_on timestamptz DEFAULT now(),
  demand_id bigint REFERENCES hostel.fee_demand,
  status varchar(40) NOT NULL DEFAULT 'Requested' CHECK (status IN ('Requested', 'Approved', 'Rejected', 'Completed', 'Cancelled')),
  created_at timestamptz NOT NULL DEFAULT now(), created_by varchar(20), updated_at timestamptz, updated_by varchar(20)
);
COMMENT ON TABLE hostel.convention_booking IS 'v2.1 K3 Convention_Booking. One row per: booking of a slot on a date';

-- K4 Booking_Guest: one row per friend on the guest list
CREATE TABLE hostel.booking_guest (
  booking_id bigint NOT NULL REFERENCES hostel.convention_booking,
  guest_student_id varchar(20) NOT NULL REFERENCES ref.student_master,
  checked_in_at timestamptz,
  checked_in_by varchar(20) REFERENCES ref.staff_master,
  PRIMARY KEY (booking_id, guest_student_id),
  created_at timestamptz NOT NULL DEFAULT now(), created_by varchar(20), updated_at timestamptz, updated_by varchar(20)
);
COMMENT ON TABLE hostel.booking_guest IS 'v2.1 K4 Booking_Guest. One row per: friend on the guest list';

-- K5 Booking_Food_Order: one row per food or drink item required for a booking
CREATE TABLE hostel.booking_food_order (
  booking_id bigint NOT NULL REFERENCES hostel.convention_booking,
  line_no bigint NOT NULL,
  item_type varchar(40) NOT NULL CHECK (item_type IN ('Food', 'Soft_Drink')),
  item_name text NOT NULL,
  qty numeric(12,3) NOT NULL,
  served_qty numeric(12,3),
  remarks text,
  PRIMARY KEY (booking_id, line_no),
  created_at timestamptz NOT NULL DEFAULT now(), created_by varchar(20), updated_at timestamptz, updated_by varchar(20)
);
COMMENT ON TABLE hostel.booking_food_order IS 'v2.1 K5 Booking_Food_Order. One row per: food or drink item required for a booking';

-- K6 Event_Report: one row per report on a completed event
CREATE TABLE hostel.event_report (
  booking_id bigint NOT NULL REFERENCES hostel.convention_booking,
  actual_start timestamptz NOT NULL,
  actual_end timestamptz NOT NULL,
  guests_attended numeric(12,2),
  security_staff_id varchar(20) NOT NULL REFERENCES ref.staff_master,
  food_service_ok boolean NOT NULL DEFAULT false,
  issues_occurred boolean NOT NULL DEFAULT false,
  issue_details text,
  hall_condition varchar(40) NOT NULL CHECK (hall_condition IN ('Good', 'Needs_Cleaning', 'Damaged')),
  reported_by varchar(20) REFERENCES ref.staff_master,
  reported_at timestamptz,
  PRIMARY KEY (booking_id),
  created_at timestamptz NOT NULL DEFAULT now(), created_by varchar(20), updated_at timestamptz, updated_by varchar(20)
);
COMMENT ON TABLE hostel.event_report IS 'v2.1 K6 Event_Report. One row per: report on a completed event';

-- L2 Academic_Term: one row per semester or trimester
CREATE TABLE acad.academic_term (
  term_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  academic_year varchar(9) NOT NULL REFERENCES hostel.academic_year,
  term_type varchar(40) NOT NULL CHECK (term_type IN ('Semester', 'Trimester')),
  term_no integer NOT NULL,
  start_date date NOT NULL,
  end_date date NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(), created_by varchar(20), updated_at timestamptz, updated_by varchar(20)
);
COMMENT ON TABLE acad.academic_term IS 'v2.1 L2 Academic_Term. One row per: semester or trimester';

-- L3 Class_Attendance_Daily: one row per student per class day
CREATE TABLE acad.class_attendance_daily (
  student_id varchar(20) NOT NULL REFERENCES ref.student_master,
  att_date date NOT NULL,
  classes_held numeric(12,2),
  classes_attended numeric(12,2),
  batch_id bigint REFERENCES shared.import_batch,
  PRIMARY KEY (student_id, att_date),
  created_at timestamptz NOT NULL DEFAULT now(), created_by varchar(20), updated_at timestamptz, updated_by varchar(20)
);
COMMENT ON TABLE acad.class_attendance_daily IS 'v2.1 L3 Class_Attendance_Daily. One row per: student per class day';

-- L4 Evaluation_Marks: one row per mark of a student in one course in one evaluation
CREATE TABLE acad.evaluation_marks (
  student_id varchar(20) NOT NULL REFERENCES ref.student_master,
  term_id bigint NOT NULL REFERENCES acad.academic_term,
  course_code varchar(60) NOT NULL,
  evaluation_type varchar(40) NOT NULL CHECK (evaluation_type IN ('In_Sem', 'End_Sem')),
  evaluation_name varchar(60) NOT NULL,
  max_marks numeric(12,2),
  marks_obtained numeric(12,2),
  batch_id bigint REFERENCES shared.import_batch,
  PRIMARY KEY (student_id, term_id, course_code, evaluation_type, evaluation_name),
  created_at timestamptz NOT NULL DEFAULT now(), created_by varchar(20), updated_at timestamptz, updated_by varchar(20)
);
COMMENT ON TABLE acad.evaluation_marks IS 'v2.1 L4 Evaluation_Marks. One row per: mark of a student in one course in one evaluation';

-- L5 Term_Status: one row per student per term
CREATE TABLE acad.term_status (
  student_id varchar(20) NOT NULL REFERENCES ref.student_master,
  term_id bigint NOT NULL REFERENCES acad.academic_term,
  cumulative_attendance_pct numeric(12,2),
  result_status varchar(40) CHECK (result_status IN ('In_Progress', 'Promoted', 'Condoned', 'Detained')),
  batch_id bigint REFERENCES shared.import_batch,
  updated_at timestamptz,
  PRIMARY KEY (student_id, term_id),
  created_at timestamptz NOT NULL DEFAULT now(), created_by varchar(20), updated_by varchar(20)
);
COMMENT ON TABLE acad.term_status IS 'v2.1 L5 Term_Status. One row per: student per term';

-- M3 Exam_Schedule: one row per examination of a student (imported)
CREATE TABLE hostel.exam_schedule (
  student_id varchar(20) NOT NULL REFERENCES ref.student_master,
  term_id bigint NOT NULL REFERENCES acad.academic_term,
  exam_name varchar(60) NOT NULL,
  exam_start date,
  exam_end date,
  batch_id bigint REFERENCES shared.import_batch,
  PRIMARY KEY (student_id, term_id, exam_name),
  created_at timestamptz NOT NULL DEFAULT now(), created_by varchar(20), updated_at timestamptz, updated_by varchar(20)
);
COMMENT ON TABLE hostel.exam_schedule IS 'v2.1 M3 Exam_Schedule. One row per: examination of a student (imported)';

-- M4 Exam_Alert: one row per alarm that a punished student has an examination
CREATE TABLE hostel.exam_alert (
  alert_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  punishment_id bigint REFERENCES hostel.discipline_punishment,
  student_id varchar(20) REFERENCES ref.student_master,
  exam_name text,
  exam_start date,
  exam_state varchar(40) CHECK (exam_state IN ('Upcoming', 'Ongoing')),
  raised_at timestamptz DEFAULT now(),
  coe_ack_by varchar(20) NOT NULL REFERENCES ref.staff_master,
  coe_ack_at timestamptz,
  director_ack_by varchar(20) NOT NULL REFERENCES ref.staff_master,
  director_ack_at timestamptz,
  decision_note text,
  status varchar(40) NOT NULL DEFAULT 'Open' CHECK (status IN ('Open', 'Acknowledged', 'Closed')),
  created_at timestamptz NOT NULL DEFAULT now(), created_by varchar(20), updated_at timestamptz, updated_by varchar(20)
);
COMMENT ON TABLE hostel.exam_alert IS 'v2.1 M4 Exam_Alert. One row per: alarm that a punished student has an examination';


-- ---------- items added to tables that exist ----------
ALTER TABLE ref.student_master ADD COLUMN IF NOT EXISTS photo varchar(200);
ALTER TABLE hostel.mess_master ADD COLUMN IF NOT EXISTS store_code varchar(10) REFERENCES portal.location;
ALTER TABLE infra.maintenance_ticket ADD COLUMN IF NOT EXISTS source varchar(40) CHECK (source IN ('Student_QR', 'Floor_Inspection', 'Warden_Inspection', 'Office'));
ALTER TABLE infra.maintenance_ticket ADD COLUMN IF NOT EXISTS ticket_group varchar(40) CHECK (ticket_group IN ('Electrical', 'Furniture_Doors', 'Plumbing', 'Other'));
ALTER TABLE infra.maintenance_ticket ADD COLUMN IF NOT EXISTS item varchar(40) CHECK (item IN ('Light', 'Fan', 'Air_Conditioner', 'Socket', 'Cot', 'Table', 'Chair', 'Cupboard', 'Door', 'Tap', 'Flush', 'Drain', 'Other'));
ALTER TABLE infra.maintenance_ticket ADD COLUMN IF NOT EXISTS photo_doc_id uuid REFERENCES shared.document;
ALTER TABLE infra.maintenance_ticket ADD COLUMN IF NOT EXISTS l1_decision varchar(40) CHECK (l1_decision IN ('Genuine', 'Not_Genuine'));
ALTER TABLE infra.maintenance_ticket ADD COLUMN IF NOT EXISTS l1_by varchar(20) REFERENCES ref.staff_master;
ALTER TABLE infra.maintenance_ticket ADD COLUMN IF NOT EXISTS l1_at timestamptz;
ALTER TABLE infra.maintenance_ticket ADD COLUMN IF NOT EXISTS l1_remarks text;
ALTER TABLE infra.maintenance_ticket ADD COLUMN IF NOT EXISTS escalated_at timestamptz;
ALTER TABLE infra.maintenance_ticket ADD COLUMN IF NOT EXISTS supervisor_id varchar(20) REFERENCES ref.staff_master;
ALTER TABLE infra.maintenance_ticket ADD COLUMN IF NOT EXISTS closure_due_at timestamptz;
ALTER TABLE infra.maintenance_ticket ADD COLUMN IF NOT EXISTS closure_by varchar(20) REFERENCES ref.staff_master;
ALTER TABLE infra.maintenance_ticket ADD COLUMN IF NOT EXISTS closure_at timestamptz;
ALTER TABLE infra.maintenance_ticket ADD COLUMN IF NOT EXISTS student_confirmed boolean;
